using System;using System.Data;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmReports:StyledForm { DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};public FrmReports(){Text="Reports";Size=new Size(1000,600);var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55,Padding=new Padding(8)};var reg=new Button{Text="Registration Report",Width=145};var refund=new Button{Text="Refund Report",Width=120};var export=new Button{Text="Export Excel CSV",Width=140};p.Controls.Add(reg);p.Controls.Add(refund);p.Controls.Add(export);reg.Click+=delegate{g.DataSource=new ReportQuery().Registration();};refund.Click+=delegate{g.DataSource=new ReportQuery().Refunds();};export.Click+=delegate{var t=g.DataSource as DataTable;if(t==null)return;using(var s=new SaveFileDialog{Filter="Excel-compatible CSV|*.csv",FileName="UCS-Pyay-Report.csv"})if(s.ShowDialog()==DialogResult.OK){ExcelExportHelper.ExportCsv(t,s.FileName);MessageBox.Show("Report exported.");}};Controls.Add(g);Controls.Add(p);reg.PerformClick();} } }
